# DDIA Chapter 3: LSM-Tree Storage Engine with WAL and Compaction
import os
class LSMTree:
    def __init__(self, wal_path='wal.log'):
        self.wal_path, self.memtable, self.sstables = wal_path, {}, []
    def put(self, key, val):
        with open(self.wal_path, 'a') as f: f.write(f'{key}:{val}\n')
        self.memtable[key] = val
        if len(self.memtable) >= 3:
            self.sstables.append(sorted(self.memtable.items()))
            self.memtable.clear()
            if os.path.exists(self.wal_path): os.remove(self.wal_path)
    def get(self, key):
        if key in self.memtable: return None if self.memtable[key] == '__tombstone__' else self.memtable[key]
        for sstable in reversed(self.sstables):
            for k, v in sstable:
                if k == key: return None if v == '__tombstone__' else v
        return None
    def delete(self, key): self.put(key, '__tombstone__')

# DDIA Chapter 3: B-Tree Index with Page Layouts and Page Splits
class BTreeNode:
    def __init__(self, is_leaf=True, max_keys=3):
        self.is_leaf, self.max_keys, self.keys, self.values = is_leaf, max_keys, [], []
class BTreeIndex:
    def __init__(self): self.root = BTreeNode(is_leaf=True)
    def put(self, key, val):
        node = self.root
        if len(node.keys) >= node.max_keys:
            new_root = BTreeNode(is_leaf=False)
            new_root.values.append(self.root)
            self._split_child(new_root, 0, self.root)
            self.root = new_root
        self._insert_non_full(self.root, key, val)
    def _split_child(self, parent, i, child):
        mid = len(child.keys) // 2
        sibling = BTreeNode(is_leaf=child.is_leaf)
        parent.keys.insert(i, child.keys[mid])
        parent.values.insert(i + 1, sibling)
        sibling.keys, sibling.values = child.keys[mid + 1:], child.values[mid + 1:]
        child.keys, child.values = child.keys[:mid], child.values[:mid]
    def _insert_non_full(self, node, key, val):
        if node.is_leaf:
            if key in node.keys: node.values[node.keys.index(key)] = val
            else:
                node.keys.append(key); node.values.append(val)
                comb = sorted(zip(node.keys, node.values))
                node.keys, node.values = [k for k, v in comb], [v for k, v in comb]
        else:
            idx = 0
            while idx < len(node.keys) and key > node.keys[idx]: idx += 1
            child = node.values[idx]
            if len(child.keys) >= child.max_keys:
                self._split_child(node, idx, child)
                if key > node.keys[idx]: child = node.values[idx + 1]
            self._insert_non_full(child, key, val)
    def get(self, key): return self._search(self.root, key)
    def _search(self, node, key):
        if node.is_leaf:
            for i, k in enumerate(node.keys): 
                if k == key: return node.values[i]
            return None
        idx = 0
        while idx < len(node.keys) and key > node.keys[idx]: idx += 1
        return self._search(node.values[idx], key)

# DDIA Chapter 2: Document Model with Nested Schema and JSON Parsing
import json
class DocumentStore:
    def __init__(self): self.documents = {}
    def insert(self, doc_id, doc_str): self.documents[doc_id] = json.loads(doc_str)
    def get_nested(self, doc_id, path):
        doc = self.documents.get(doc_id)
        for key in path:
            if isinstance(doc, dict): doc = doc.get(key)
            else: return None
        return doc

# DDIA Chapter 6: Key-Range Partitioning Router
class RangeRouter:
    def __init__(self): self.boundaries = [('A', 'M', 'Node-0'), ('N', 'Z', 'Node-1')]
    def route(self, key):
        for start, end, node in self.boundaries:
            if start <= key[0].upper() <= end: return node
        return 'Node-Fallback'

# DDIA Chapter 4: Binary Protobuf Encoding with Tag Varints
class ProtobufEncoder:
    @staticmethod
    def encode_field(tag, val_type, value):
        header = (tag << 3) | val_type
        if val_type == 0: return bytes([header, value])
        elif val_type == 2:
            payload = str(value).encode('utf-8')
            return bytes([header, len(payload)]) + payload
        return b''

# DDIA Chapter 4: Avro Binary Packing without Tag Headers
class AvroEncoder:
    def __init__(self, schema): self.schema = schema
    def encode(self, record):
        packed = b''
        for field, f_type in self.schema:
            val = record[field]
            if f_type == 'string':
                payload = str(val).encode('utf-8')
                packed += bytes([len(payload)]) + payload
            elif f_type == 'int': packed += bytes([val])
        return packed

# DDIA Chapter 9: Raft Consensus Term Validation and Log Quorum voting
class RaftReplica:
    def __init__(self, replica_id): self.id, self.term, self.state = replica_id, 0, 'Follower'
    def request_vote(self, term, candidate_id):
        if term > self.term: self.term, self.state = term, 'Follower'; return True
        return False
    def trigger_election(self, peers):
        self.state, self.term, votes = 'Candidate', self.term + 1, 1
        for p in peers:
            if p.request_vote(self.term, self.id): votes += 1
        if votes > (len(peers) + 1) // 2: self.state = 'Leader'

# DDIA Chapter 9: Two-Phase Commit (2PC) coordinator log & participant votes
class Coordinator2PC:
    def __init__(self, participants): self.participants = participants
    def commit_tx(self, tx_id):
        votes = [p.prepare(tx_id) for p in self.participants]
        if all(votes):
            for p in self.participants: p.commit(tx_id)
            return 'Committed'
        for p in self.participants: p.abort(tx_id)
        return 'Aborted'

# DDIA Chapter 5: Single-Leader Replication with Lag & Read-After-Write Routing
class SingleLeaderDB:
    def __init__(self): self.leader, self.replicas = {}, [{}, {}]
    def write(self, key, val, client_id):
        self.leader[key] = (val, client_id)
        for r in self.replicas: r[key] = (val, client_id)
    def read(self, key, client_id, from_user_profile=False):
        if from_user_profile:
            res = self.leader.get(key)
            return res[0] if res else None
        res = self.replicas[0].get(key)
        return res[0] if res else None

# DDIA Chapter 5: Leaderless Quorum with Read Repair
class LeaderlessQuorum:
    def __init__(self, n=3, r=2, w=2):
        self.nodes, self.r, self.w = [{'store': {}, 'version': {}} for _ in range(n)], r, w
    def write(self, key, val):
        successes = 0
        version = self._get_next_version(key) + 1
        for node in self.nodes:
            node['store'][key], node['version'][key] = val, version
            successes += 1
        if successes < self.w: raise RuntimeError('Write Quorum Failed')
    def read(self, key):
        responses = [(node['store'][key], node['version'][key], i) for i, node in enumerate(self.nodes) if key in node['store']]
        if len(responses) < self.r: return None
        max_ver = max(r[1] for r in responses)
        newest_val = next(r[0] for r in responses if r[1] == max_ver)
        for val, ver, idx in responses:
            if ver < max_ver:
                self.nodes[idx]['store'][key], self.nodes[idx]['version'][key] = newest_val, max_ver
        return newest_val
    def _get_next_version(self, key):
        vers = [n['version'].get(key, 0) for n in self.nodes]
        return max(vers) if vers else 0

# ODS: Treap randomized priority BST
import random
class TreapNode:
    def __init__(self, key, val):
        self.key, self.val, self.priority = key, val, random.random()
        self.left = self.right = None
class Treap:
    def __init__(self): self.root = None
    def _rotate_left(self, u):
        w = u.right; u.right = w.left; w.left = u; return w
    def _rotate_right(self, u):
        w = u.left; u.left = w.right; w.right = u; return w
    def put(self, key, val):
        self.root = self._insert(self.root, key, val)
    def _insert(self, node, key, val):
        if not node: return TreapNode(key, val)
        if key < node.key:
            node.left = self._insert(node.left, key, val)
            if node.left.priority < node.priority: node = self._rotate_right(node)
        else:
            node.right = self._insert(node.right, key, val)
            if node.right.priority < node.priority: node = self._rotate_left(node)
        return node

# ODS: AVL Tree height-balanced BST
class AVLNode:
    def __init__(self, key, val):
        self.key, self.val, self.height = key, val, 1
        self.left = self.right = None
class AVLTree:
    def __init__(self): self.root = None
    def _height(self, n): return n.height if n else 0
    def _get_balance(self, n): return self._height(n.left) - self._height(n.right) if n else 0
    def _rotate_left(self, z):
        y = z.right; T2 = y.left; y.left = z; z.right = T2
        z.height = 1 + max(self._height(z.left), self._height(z.right))
        y.height = 1 + max(self._height(y.left), self._height(y.right))
        return y
    def _rotate_right(self, z):
        y = z.left; T3 = y.right; y.right = z; z.left = T3
        z.height = 1 + max(self._height(z.left), self._height(z.right))
        y.height = 1 + max(self._height(y.left), self._height(y.right))
        return y
    def put(self, key, val):
        self.root = self._insert(self.root, key, val)
    def _insert(self, node, key, val):
        if not node: return AVLNode(key, val)
        if key < node.key: node.left = self._insert(node.left, key, val)
        else: node.right = self._insert(node.right, key, val)
        node.height = 1 + max(self._height(node.left), self._height(node.right))
        balance = self._get_balance(node)
        if balance > 1 and key < node.left.key: return self._rotate_right(node)
        if balance < -1 and key > node.right.key: return self._rotate_left(node)
        if balance > 1 and key > node.left.key:
            node.left = self._rotate_left(node.left)
            return self._rotate_right(node)
        if balance < -1 and key < node.right.key:
            node.right = self._rotate_right(node.right)
            return self._rotate_left(node)
        return node

# SICP: Metacircular Evaluator environment model
class EnvFrame:
    def __init__(self, parent=None):
        self.bindings, self.parent = {}, parent
    def lookup(self, var):
        if var in self.bindings: return self.bindings[var]
        if self.parent: return self.parent.lookup(var)
        raise NameError(f'Unbound: {var}')
    def define(self, var, val): self.bindings[var] = val
def sicp_eval(exp, env):
    if isinstance(exp, (int, float, str)) and not isinstance(exp, str): return exp
    if isinstance(exp, str): return env.lookup(exp)
    if isinstance(exp, list):
        if exp[0] == 'define': env.define(exp[1], sicp_eval(exp[2], env)); return None
        fn = sicp_eval(exp[0], env)
        args = [sicp_eval(arg, env) for arg in exp[1:]]
        return fn(*args)

# SICP: Infinite Stream delayed evaluation
class LazyStream:
    def __init__(self, head, tail_thunk):
        self.head, self._tail_thunk, self._tail = head, tail_thunk, None
    @property
    def tail(self):
        if not self._tail: self._tail = self._tail_thunk()
        return self._tail

# Linux Kernel: Power-of-two lockless ring buffer (kfifo)
class LinuxKfifo:
    def __init__(self, size=1024):
        assert (size & (size - 1)) == 0, 'Size must be power of two'
        self.size, self.buffer, self.in_idx, self.out_idx = size, [None] * size, 0, 0
    def put(self, val):
        if self.in_idx - self.out_idx == self.size: return False
        self.buffer[self.in_idx & (self.size - 1)] = val
        self.in_idx += 1; return True
    def get(self):
        if self.in_idx == self.out_idx: return None
        val = self.buffer[self.out_idx & (self.size - 1)]
        self.out_idx += 1; return val

# Design Patterns: Strategy Pattern
class SortingStrategy:
    def sort(self, data): pass
class QuickSort(SortingStrategy):
    def sort(self, data): return sorted(data)
class SortedList:
    def __init__(self, strategy: SortingStrategy): self.strategy = strategy
    def execute(self, data): return self.strategy.sort(data)

# Design Patterns: Observer Pattern
class Subject:
    def __init__(self): self._observers = []
    def attach(self, obs): self._observers.append(obs)
    def notify(self, msg):
        for obs in self._observers: obs.update(msg)
class Observer:
    def update(self, msg): pass
